export function getWorkspaceNotifications(kind, db = getStore()) {
  if (kind === 'client') {
    const properties = db.properties.filter((property) => property.client === 'Meridian Workspaces');
    const orders = db.workOrders.filter((order) => order.client === 'Meridian Workspaces');
    const invoices = db.invoices.filter((invoice) => invoice.client === 'Meridian Workspaces');
    return db.notifications.filter((notification) => {
      const content = `${notification.title} ${notification.body}`;
      return properties.some((property) => content.includes(property.name))
        || orders.some((order) => content.includes(order.id))
        || invoices.some((invoice) => content.includes(invoice.id));
    });
  }
  if (kind === 'technician') {
    const assignments = db.workOrders.filter((order) => order.assignee === 'Senthil Kumar');
    return db.notifications.filter((notification) => {
      const content = `${notification.title} ${notification.body}`;
      return assignments.some((order) => content.includes(order.id) || content.includes(order.property));
    });
  }
  return db.notifications;
}

