const fmt = (value) => new Intl.NumberFormat(siteConfig.currencyLocale).format(value);
const money = (value) => new Intl.NumberFormat(siteConfig.currencyLocale, { style: 'currency', currency: siteConfig.currency, maximumFractionDigits: 0 }).format(value);
const indiaDateParts = (date = new Date()) => Object.fromEntries(new Intl.DateTimeFormat('en-CA', { timeZone: siteConfig.timezone, year: 'numeric', month: '2-digit', day: '2-digit' }).formatToParts(date).map((part) => [part.type, part.value]));
const todayISO = () => { const { year, month, day } = indiaDateParts(); return `${year}-${month}-${day}`; };
const currentMonthISO = () => todayISO().slice(0, 7);
const todayLabel = () => new Intl.DateTimeFormat('en-IN', { timeZone: siteConfig.timezone, day: '2-digit', month: 'short', year: 'numeric' }).format(new Date());
const currentMonthLabel = () => new Intl.DateTimeFormat('en-IN', { timeZone: siteConfig.timezone, month: 'long', year: 'numeric' }).format(new Date());
const todayLongLabel = () => new Intl.DateTimeFormat('en-IN', { timeZone: siteConfig.timezone, weekday: 'long', day: 'numeric', month: 'long', year: 'numeric' }).format(new Date()).toUpperCase();
const shiftISODate = (date, days) => { const shifted = new Date(`${date}T12:00:00Z`); shifted.setUTCDate(shifted.getUTCDate() + days); return shifted.toISOString().slice(0, 10); };
const dateShort = (date) => { if (!date) return '—'; const d = new Date(`${date}T12:00:00+05:30`); return Number.isNaN(d.getTime()) ? esc(date) : new Intl.DateTimeFormat('en-IN', { month: 'short', day: 'numeric', timeZone: siteConfig.timezone }).format(d); };
const isWorkOrderActive = (status) => !['Completed', 'Client Approval', 'Closed', 'Cancelled'].includes(status);
const isWorkOrderCompleted = (status) => ['Completed', 'Client Approval', 'Closed'].includes(status);

function metricCard(label, value, change, ico, color = '') {
  return `<article class="metric-card"><div class="metric-top"><span>${label}</span><span class="metric-icon ${color}">${icon(ico, 18)}</span></div><div class="metric-value">${value}</div><div class="metric-foot"><span class="metric-change">${icon('activity', 13)} ${change}</span><span> data</span></div></article>`;
}

function adminOverview(db) {
  const month = currentMonthISO();
  const today = todayISO();
  const workOrders = db.workOrders;
  const activeOrders = workOrders.filter((order) => isWorkOrderActive(order.status));
  const completedThisMonth = workOrders.filter((order) => isWorkOrderCompleted(order.status) && String(order.date || '').startsWith(month)).length;
  const urgent = activeOrders.filter((order) => ['High', 'Critical'].includes(order.priority)).length;
  const schedulesNextSevenDays = db.schedules
    .filter((event) => event.due >= today && event.due <= shiftISODate(today, 6))
    .sort((a, b) => String(a.due).localeCompare(String(b.due)));
  const statusNames = ['New', 'Pending Review', 'Assigned', 'Dispatched', 'In Progress', 'On Hold', 'Waiting for Parts', 'Completed', 'Client Approval', 'Closed', 'Cancelled'];
  const statusCounts = statusNames.map((status) => ({ status, count: workOrders.filter((order) => order.status === status).length }));
  const maxStatusCount = Math.max(1, ...statusCounts.map((item) => item.count));
  const chartScale = [maxStatusCount, Math.ceil(maxStatusCount * .75), Math.ceil(maxStatusCount * .5), Math.ceil(maxStatusCount * .25), 0];
  const categoryBuckets = [
    { label: 'Maintenance', className: 'legend-maintenance', test: (category) => ['Maintenance', 'Preventive'].includes(category) },
    { label: 'HVAC', className: 'legend-hvac', test: (category) => category === 'HVAC' },
    { label: 'Electrical', className: 'legend-electrical', test: (category) => category === 'Electrical' },
    { label: 'Cleaning', className: 'legend-cleaning', test: (category) => category === 'Cleaning' },
    { label: 'Other', className: 'legend-other', test: (category) => !['Maintenance', 'Preventive', 'HVAC', 'Electrical', 'Cleaning'].includes(category) }
  ];
  let assignedPercent = 0;
  const categoryCounts = categoryBuckets.map((bucket, index) => {
    const count = activeOrders.filter((order) => bucket.test(order.category)).length;
    const percent = index === categoryBuckets.length - 1 ? 100 - assignedPercent : activeOrders.length ? Math.round(count / activeOrders.length * 100) : 0;
    assignedPercent += percent;
    return { ...bucket, count, percent };
  });
  const colors = ['#4e826b', '#91ad91', '#b8c8a9', '#d5b276', '#dfe6dc'];
  let angle = 0;
  const gradientStops = categoryCounts.map((item, index) => {
    const next = angle + item.percent;
    const stop = `${colors[index]} ${angle}% ${next}%`;
    angle = next;
    return stop;
  });
  const categoryGradient = `conic-gradient(${gradientStops.join(',')})`;
  const technicians = db.technicians;
  const availability = {
    available: technicians.filter((tech) => tech.status === 'Available').length,
    onSite: technicians.filter((tech) => tech.status === 'On site').length,
    offline: technicians.filter((tech) => !['Available', 'On site'].includes(tech.status)).length
  };
  const title = titles['/admin/dashboard'];
  return `<div class="page-heading"><div><div class="page-kicker">${todayLongLabel()} <span class="live-indicator"></span></div><h1>${title[0]}</h1><p>${title[1]} Figures below are generated from the bundled sample records.</p></div><div class="heading-actions"><button class="btn btn-outline btn-small" data-action="export-csv" data-export="workOrders">${icon('download', 15)} Export</button><button class="btn btn-primary btn-small" data-action="open-create" data-entity="work-order">${icon('plus', 16)} New work order</button></div></div>
    <div class="metric-grid admin-metrics">${metricCard('Sample clients', fmt(db.clients.length), 'Sample records', 'users', 'metric-icon-green')}${metricCard('Active work orders', fmt(activeOrders.length), 'Current sample count', 'clipboard', 'metric-icon-amber')}${metricCard('Completed this month', fmt(completedThisMonth), 'Date-scoped sample records', 'checkCircle', 'metric-icon-blue')}${metricCard('Visits in next 7 days', fmt(schedulesNextSevenDays.length), 'Sample maintenance schedule', 'calendar', 'metric-icon-violet')}</div>
    <div class="admin-dashboard-grid"><section class="panel orders-chart-panel"><div class="panel-heading"><div><h2>Work orders by status</h2><p>${fmt(workOrders.length)} bundled sample records</p></div><div class="panel-heading-actions"><span class="chart-key"><i></i> Sample records</span><span class="select-compact" title="Counts are calculated from this browser workspace dataset"></span></div></div><div class="orders-chart"><div class="chart-y">${chartScale.map((value) => `<span>${value}</span>`).join('')}</div><div class="chart-area"><div class="chart-grid-lines"><i></i><i></i><i></i><i></i><i></i></div><div class="grouped-bars">${statusCounts.map(({ status, count }) => `<div class="bar-group" aria-label="${esc(status)}: ${count} sample work orders"><span class="bar received" style="--bar:${Math.round(count / maxStatusCount * 100)}%"></span><small>${esc(status)}</small></div>`).join('')}</div></div></div><ul class="mobile-status-list" aria-label="Sample work orders by status">${statusCounts.map(({ status, count }) => `<li class="mobile-status-row"><span class="mobile-status-name">${esc(status)}</span><span class="mobile-status-meter" aria-hidden="true"><i style="--bar:${Math.round(count / maxStatusCount * 100)}%"></i></span><strong class="mobile-status-count">${count}</strong></li>`).join('')}</ul><div class="chart-footnote">${icon('activity', 14)} Counts update with the local sample records; they are not live operational reporting.</div></section>
      <section class="panel category-panel"><div class="panel-heading"><div><h2>Active service categories</h2><p>${fmt(activeOrders.length)} active sample work orders</p></div><span class="icon-button subtle" aria-hidden="true">${icon('more', 18)}</span></div><div class="category-chart-wrap"><div class="category-donut" style="background:${categoryGradient}" role="img" aria-label="Active sample work orders by category: ${categoryCounts.map((item) => `${item.label} ${item.count} (${item.percent} percent)`).join(', ')}"><div><strong>${fmt(activeOrders.length)}</strong><span>ACTIVE SAMPLE</span></div></div><div class="category-legend">${categoryCounts.map((item) => `<span title="${item.count} active sample work orders"><i class="${item.className}"></i>${item.label}<b>${item.percent}%</b></span>`).join('')}</div></div><a class="panel-link" href="#/admin/reports">View sample report ${icon('arrow', 14)}</a></section>
      <section class="panel recent-orders-panel"><div class="panel-heading"><div><h2>Work needing attention</h2><p>${fmt(urgent)} high or critical active sample requests</p></div><a href="#/admin/work-orders" class="panel-link">All work orders ${icon('arrow', 14)}</a></div><div class="table-wrap compact-table"><table><thead><tr><th scope="col">WORK ORDER</th><th scope="col">PROPERTY</th><th scope="col">PRIORITY</th><th scope="col">STATUS</th></tr></thead><tbody>${activeOrders.slice(0, 5).map((order) => `<tr><td><a class="table-primary-link" href="#/admin/work-orders">${esc(order.id)}<small>${esc(order.title)}</small></a></td><td>${esc(order.property)}</td><td>${statusBadge(order.priority)}</td><td>${statusBadge(order.status)}</td></tr>`).join('')}</tbody></table></div></section>
      <section class="panel technician-panel"><div class="panel-heading"><div><h2>Technician availability</h2><p>${fmt(technicians.length)} sample profiles</p></div><a href="#/admin/technicians" class="panel-link">Team view ${icon('arrow', 14)}</a></div><div class="tech-list">${technicians.slice(0, 4).map((tech) => `<div class="tech-list-item">${avatar(tech.name, 'avatar-sm avatar-palette')}<span class="tech-list-name"><strong>${esc(tech.name)}</strong><small>${esc(tech.skills.split(' · ')[0])}</small></span><span class="tech-presence ${tech.status === 'Available' ? 'presence-available' : tech.status === 'On site' ? 'presence-busy' : 'presence-away'}"><i></i>${esc(tech.status)}</span></div>`).join('')}</div><div class="availability-summary"><span><i class="presence-available-dot"></i>${availability.available} Available</span><span><i class="presence-busy-dot"></i>${availability.onSite} On site</span><span><i class="presence-offline-dot"></i>${availability.offline} Other</span></div></section></div><div class="dashboard-bottom-grid"><section class="panel maintenance-panel"><div class="panel-heading"><div><h2>Upcoming maintenance</h2><p>Next 7 days · ${fmt(schedulesNextSevenDays.length)} sample visits</p></div><a href="#/admin/maintenance" class="panel-link">Calendar ${icon('arrow', 14)}</a></div><div class="upcoming-list">${schedulesNextSevenDays.length ? schedulesNextSevenDays.slice(0, 4).map((event) => `<div class="upcoming-item"><div class="date-block"><strong>${dateShort(event.due).split(' ')[1]}</strong><span>${dateShort(event.due).split(' ')[0]}</span></div><div class="upcoming-copy"><strong>${esc(event.title)}</strong><span>${esc(event.property)} · ${esc(event.technician)}</span></div><span class="upcoming-category">${esc(event.service)}</span></div>`).join('') : '<div class="empty-state"><strong>No sample visits due in the next 7 days</strong></div>'}</div></section><section class="panel health-panel"><div class="panel-heading"><div><h2>Property health</h2><p>Illustrative readiness scores ·  Sites</p></div><a href="#/admin/properties" class="panel-link">View properties ${icon('arrow', 14)}</a></div><div class="health-property-list">${db.properties.slice(0, 4).map((property) => `<div class="health-property"><div class="health-property-meta"><strong>${esc(property.name)}</strong><span>${property.health}%</span></div><div class="health-meter"><i style="--health:${property.health}%"></i></div><small>${esc(property.client)}</small></div>`).join('')}</div></section></div>`;
}

